import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { areas, project } from "./site-data.mjs";

const root=process.cwd(); const out=path.join(root,"site"); const config=JSON.parse(fs.readFileSync(path.join(root,"site.config.json"),"utf8"));
const esc=(v)=>String(v).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
const abs=(route)=>`${config.baseUrl.replace(/\/$/,"")}${route}`; const sRoute=(s)=>`/services/${s.slug}/`; const aRoute=(a)=>`/service-areas/${a.slug}/`; const areaH1=(a)=>a.slug==="houston"?`${project.topic} Service Area in Houston, TX`:`${project.topic} in ${a.label}, TX`;
const groups=[...new Set(project.services.map(s=>s.group))]; const areaGroups=[...new Set(areas.map(a=>a.region))].map(label=>({label,areas:areas.filter(a=>a.region===label)}));
const serviceBySlug=Object.fromEntries(project.services.map(s=>[s.slug,s]));

function brand(){return `<a class="brand" href="/" aria-label="${esc(project.name)} home"><span class="mark" aria-hidden="true"><i></i><i></i><i></i></span><span><b>${esc(project.name)}</b><small>Greater Houston service map</small></span></a>`}
function serviceMenu(){return groups.map(group=>`<div class="menu-group"><strong>${esc(group)}</strong>${project.services.filter(s=>s.group===group).map(s=>`<a href="${sRoute(s)}">${esc(s.label)}</a>`).join("")}</div>`).join("")}
function areaMenu(){return areaGroups.map(group=>`<div class="menu-group"><strong>${esc(group.label)}</strong>${group.areas.map(a=>`<a href="${aRoute(a)}">${esc(a.label)}</a>`).join("")}</div>`).join("")}
function header(active=""){return `<div class="status"><div class="shell"><span></span>${esc(project.topic)} guidance for Greater Houston<b>Residential and commercial service information</b></div></div><header class="header"><div class="shell nav-shell">${brand()}<button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav" data-menu-toggle><span class="sr-only">Toggle navigation</span><i></i><i></i><i></i></button><nav id="site-nav" class="site-nav" aria-label="Primary" data-nav><div class="dropdown" data-dropdown><div class="dropdown-control"><a href="/services/"${active==="services"?' aria-current="page"':""}>Services</a><button type="button" aria-expanded="false" aria-controls="service-menu" aria-label="Show services" data-dropdown-toggle>+</button></div><div class="mega mega-services" id="service-menu">${serviceMenu()}</div></div><div class="dropdown" data-dropdown><div class="dropdown-control"><a href="/service-areas/"${active==="areas"?' aria-current="page"':""}>Service Areas</a><button type="button" aria-expanded="false" aria-controls="area-menu" aria-label="Show service areas" data-dropdown-toggle>+</button></div><div class="mega mega-areas" id="area-menu">${areaMenu()}</div></div><a href="/process/"${active==="process"?' aria-current="page"':""}>Process</a><a href="/contact/"${active==="contact"?' aria-current="page"':""}>Contact</a><a class="button nav-cta" href="/contact/">Request Service</a></nav></div></header>`}
function footer(){return `<footer class="footer"><div class="shell footer-top">${brand()}<p>Clear ${esc(project.topic.toLowerCase())} information for homes, multifamily properties, and commercial facilities throughout the Greater Houston area.</p><nav><a href="/process/">How service works</a><a href="/contact/">Request service</a><a href="/privacy/">Privacy</a></nav></div><div class="shell footer-dir"><h2>Complete Service Directory</h2><div class="footer-grid service-footer">${groups.map(g=>`<nav><strong>${esc(g)}</strong>${project.services.filter(s=>s.group===g).map(s=>`<a href="${sRoute(s)}">${esc(s.label)}</a>`).join("")}</nav>`).join("")}</div></div><div class="shell footer-dir"><h2>Greater Houston Market Directory</h2><p>Browse property, access, utility, and jurisdiction considerations for each local service area.</p><div class="footer-grid area-footer">${areaGroups.map(g=>`<nav><strong>${esc(g.label)}</strong>${g.areas.map(a=>`<a href="${aRoute(a)}">${esc(a.label)}</a>`).join("")}</nav>`).join("")}</div></div><div class="shell footer-bottom"><span>© <span data-year></span> ${esc(project.name)}</span><span>Specialty service information · Greater Houston</span></div></footer>`}
function breadcrumb(items){return {"@type":"BreadcrumbList",itemListElement:items.map((x,i)=>({"@type":"ListItem",position:i+1,name:x.name,item:abs(x.route)}))}}
function page({title,description,route,body,active="",schema=[]}){const graph=[{"@type":"WebSite","@id":`${abs("/")}#website`,name:project.name,url:abs("/"),description:project.lede},{"@type":"WebPage","@id":`${abs(route)}#webpage`,url:abs(route),name:title,description,isPartOf:{"@id":`${abs("/")}#website`}},...schema];return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="${config.indexingEnabled?"index, follow":"noindex, nofollow"}"><link rel="canonical" href="${abs(route)}"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${abs(route)}"><meta name="twitter:card" content="summary"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">${JSON.stringify({"@context":"https://schema.org","@graph":graph})}</script></head><body class="design-${project.design}"><a class="skip" href="#main-content">Skip to content</a>${header(active)}${body}${footer()}<script src="/assets/main.js" defer></script></body></html>`}
function crumbs(items){return `<nav class="crumbs" aria-label="Breadcrumb">${items.map((x,i)=>x.route?`<a href="${x.route}">${esc(x.label)}</a>${i<items.length-1?"<span>/</span>":""}`:`<b>${esc(x.label)}</b>`).join("")}</nav>`}
function hero({eyebrow,h1,intro="",items}){return `<section class="page-hero"><div class="shell">${crumbs(items)}<div class="page-hero-grid${intro?"":" page-hero-grid-title"}"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(h1)}</h1></div>${intro?`<p>${esc(intro)}</p>`:""}</div></div></section>`}
function faq(title,intro,items){return `<section class="section faq" aria-labelledby="faq-title"><div class="shell faq-grid"><div><p class="eyebrow">Frequently asked questions</p><h2 id="faq-title">${esc(title)}</h2><p>${esc(intro)}</p></div><div class="accordion">${items.map(([q,a])=>`<details><summary>${esc(q)}<span>+</span></summary><p>${esc(a)}</p></details>`).join("")}</div></div></section>`}
function finalCta(title,copy){return `<section class="final-cta"><div class="shell"><div><p class="eyebrow">Next step</p><h2>${esc(title)}</h2></div><div><p>${esc(copy)}</p><a class="button button-light" href="/contact/">Request Service</a></div></div></section>`}
function cards(list){return list.map((s,i)=>`<a class="service-card" href="${sRoute(s)}"><span>${String(i+1).padStart(2,"0")} · ${esc(s.group)}</span><h3>${esc(s.label)}</h3><p>${esc(s.outcome)}.</p><b>Open service guide →</b></a>`).join("")}

const kindCopy={
  drain:{system:"Fixtures reveal where drainage symptoms begin, but cleanouts, shared branches, and the lowest affected opening reveal how far the restriction may extend.",local:"Drain requests should identify whether one fixture, one room, or several levels are affected; that pattern changes the first access point and tool choice.",scope:"Cable size, retrieval heads, fixture protection, cleanout access, camera timing, and post-clearing flow tests belong in a useful scope."},
  repair:{system:"Water-heater diagnosis separates tank condition from controls, fuel or power, venting, pressure, recirculation, and hot-water distribution.",local:"Repair requests should include the equipment type, energy source, location, visible model information, error behavior, leak origin, and temperature pattern.",scope:"Testing, isolation, compatible parts, safety checks, restart, temperature verification, and replacement thresholds should be stated before work."},
  install:{system:"Installation combines equipment selection with utilities, access, venting or electrical capacity, drainage, safety controls, and service clearance.",local:"Installation planning should record current capacity, fuel, location, simultaneous demand, removal route, utility constraints, and any desired system change.",scope:"Equipment, labor, permits, inspections, disposal, connections, safety upgrades, commissioning, warranty registration, and finish work need explicit boundaries."},
  jetting:{system:"Effective jetting starts with pipe suitability, cleanout access, obstruction type, nozzle selection, pressure and flow, debris movement, and downstream containment.",local:"Jetting requests should include pipe material if known, recurring blockage history, available cleanouts, camera findings, occupancy, and where mobilized debris can be controlled.",scope:"Pre-inspection, setup, water source, nozzle passes, containment, cleanup, post-inspection, and structural findings should be separate line items."}
};
function serviceResearch(s){
  const label=s.label.toLowerCase(),common={
    drain:{diagnosis:`A plumber should first determine whether the symptom is isolated to one fixture, shared by a room group, or visible at the lowest opening in the building. Flow tests, trap or fixture access, cleanout access, cable feedback, and camera evidence help separate a local blockage from a main-line or structural problem.`,causes:`Likely causes include soft organic buildup, grease, hair, soap residue, foreign material, mineral or waste scale, root intrusion, a poorly aligned fitting, or a damaged section of pipe. The affected fixtures and recurrence history narrow that list.`,methods:`Cable or auger work can open a concentrated obstruction. A camera can identify location and pipe condition when the problem repeats or the cause remains unclear. Jetting may clean wall-adhered buildup in suitable piping, while broken, offset, collapsed, or badly deteriorated pipe needs a repair plan rather than more cleaning.`,verification:`The affected fixtures should drain under a realistic flow test without gurgling or returning water. When the line condition matters, post-service camera footage should show remaining deposits, roots, offsets, cracks, or other repair-relevant findings.`},
    repair:{diagnosis:`Diagnosis should begin with the equipment type, model information, age, fuel or electrical supply, stored error codes, leak origin, temperature pattern, and recent maintenance. A technician then tests the controls and components that can produce the reported symptom instead of replacing parts by guesswork.`,causes:`Possible causes include loss of power or fuel, failed controls, worn heating components, ignition trouble, restricted flow, scale or sediment, pressure problems, leaking connections, venting faults, recirculation problems, or an internally damaged tank or heat exchanger.`,methods:`A component repair makes sense when testing identifies a serviceable failure and the vessel or heat exchanger remains sound. Replacement deserves consideration when leakage comes from the tank, critical parts are unavailable, repeated failures point to broader deterioration, or the repair cost is difficult to justify against the remaining service life.`,verification:`The unit should complete a full operating cycle. Verification may include stable outlet temperature, correct ignition or element operation, safe venting, dry connections, proper pressure behavior, restored recirculation, cleared error history, and a documented explanation of any remaining risk.`},
    install:{diagnosis:`Planning starts with peak hot-water demand, current capacity, recovery or flow requirements, fuel or electrical availability, equipment location, venting, drainage, service clearance, and the route for removing and delivering equipment. Those facts determine whether a like-for-like replacement is actually appropriate.`,causes:`Installation problems often begin with an undersized or oversized unit, inadequate gas or electrical capacity, incompatible venting, missing drainage, poor service access, unsupported piping, incorrect expansion control, or equipment selected before the site was measured.`,methods:`The useful comparison is not simply tank versus tankless. Storage volume, recovery rate, temperature rise, simultaneous fixtures, utility upgrades, maintenance, available space, condensate, noise, and expected occupancy should all be compared before a model is selected.`,verification:`Commissioning should prove safe startup, correct temperature, leak-free connections, proper venting or electrical operation, functional safety controls, suitable drainage, and recovery or flow that matches the design. Required inspection and manufacturer documentation should be closed out.`},
    jetting:{diagnosis:`A camera and access review should establish pipe material, diameter, defects, standing water, blockage type, cleanout direction, downstream route, and where mobilized debris will go. Pressure and nozzle selection come after suitability is established.`,causes:`Jetting targets material attached to or accumulated along the pipe wall, such as grease, sludge, waste scale, mineral deposits, sediment, or serviceable root growth. It cannot correct a collapse, severe offset, belly, missing pipe wall, or another structural defect.`,methods:`Snaking is often appropriate for opening a concentrated obstruction. Jetting is considered when suitable piping needs broader wall cleaning or recurring deposits removed. Camera inspection supports both choices by showing whether the pipe can tolerate jetting and whether cleaning or repair is the better next step.`,verification:`A post-cleaning camera should document the accessible pipe wall, remaining deposits, root-entry points, cracks, offsets, bellies, or corrosion. Flow should be restored, debris controlled, and structural findings separated from material that additional cleaning could remove.`}
  }[project.kind];
  let signs=`Consider ${label} when ${s.situation}. Escalate the request when the condition repeats, affects more of the system, causes active leakage or overflow, interrupts normal use, or returns soon after a basic clearing or reset.`;
  let causes=common.causes,comparison=common.methods;
  if(/camera|inspection/i.test(s.label)){signs=`Invest in ${label} when a blockage keeps returning, the location is uncertain, a repair needs evidence, a property transaction requires line information, or cleaning has exposed a condition that cannot be identified from the surface.`;causes=`A camera can document roots, scale, separated or offset joints, cracks, corrosion, bellies, standing water, foreign material, and diameter changes along the accessible route. It cannot see through opaque standing water or inspect a branch the camera cannot enter.`;comparison=`Camera work answers a condition and location question; it does not remove the obstruction. A useful scope states whether minimal clearing, electronic locating, footage, still images, distance references, and a written findings summary are included.`}
  if(/root/i.test(s.label)){causes=`Roots enter through an existing joint, crack, transition, or other opening and expand where moisture is available. Removing the growth restores space in the line but does not seal the defect, so recurrence and repair options should be discussed after the pipe is visible.`}
  if(/odor/i.test(s.label)){causes=`Drain odor can come from a dry trap, contaminated overflow passage, biofilm, a failed seal, an improper or blocked vent, a hidden leak, or sewer gas escaping through a damaged connection. The odor location and when it appears are important diagnostic clues.`}
  if(/leak/i.test(s.label)){causes=`Water can escape from threaded connections, isolation valves, drain valves, relief piping, gaskets, a heat exchanger, or the storage tank itself. Drying the area and tracing the first point of moisture helps distinguish a repairable connection from vessel failure.`}
  if(/no hot water/i.test(s.label)){causes=`A no-hot-water call can involve a tripped circuit, failed element or thermostat, lost fuel supply, pilot or ignition failure, gas-control fault, blocked flow, control lockout, or a safety device responding to another condition. Testing should follow the equipment type.`}
  if(/tankless/i.test(s.label)){causes=`Tankless faults commonly involve error-code conditions, scale in the heat exchanger, restricted inlet screens, insufficient flow, ignition or flame-sensing trouble, condensate or venting problems, recirculation controls, or utility capacity that cannot support peak demand.`}
  if(/grease|kitchen/i.test(s.label)){causes=`Grease, fats, oils, food solids, soap, disposal debris, and wall-adhered residue can narrow the line over time. The service boundary should distinguish fixture or branch cleaning from interceptor pumping, downstream main cleaning, and operational source control.`}
  if(/commercial|large-diameter/i.test(s.label)){comparison+=` Commercial work also needs an occupancy and shutdown plan, equipment staging, containment, waste handling, safety zones, completion records, and a maintenance recommendation based on actual loading rather than a generic calendar.`}
  const cost=`The price of ${label} depends on access, system size and material, condition severity, diagnostic time, method, protection, shutdown constraints, permits, parts or equipment, and completion testing. A useful quote identifies those inclusions clearly.`;
  const day=`Before work begins, confirm the affected system, access route, protection plan, shutoffs, expected method, exclusions, and what would trigger a change order. The service record should identify findings, work completed, materials or equipment used, testing performed, cleanup boundaries, and any recommended follow-up.`;
  return {signs,diagnosis:common.diagnosis,causes,comparison,cost,day,verification:common.verification};
}
const decap=v=>String(v).charAt(0).toLowerCase()+String(v).slice(1);
function diagnosisHeading(s){
  const label=s.label.toLowerCase();
  if(/camera|inspection/i.test(s.label)) return `What can a ${label} reveal?`;
  if(project.kind==="install"&&/sizing/i.test(s.label)) return "How is the right water heater size calculated?";
  if(project.kind==="install") return `What should be planned before ${label}?`;
  if(project.kind==="jetting") return `How do professionals confirm ${label} is safe for the pipe?`;
  if(project.kind==="repair") return `How is a ${label} problem diagnosed?`;
  return `How do plumbers diagnose a ${label} problem?`;
}
function causeHeading(s){
  if(/camera|inspection/i.test(s.label)) return `What can ${s.label.toLowerCase()} find?`;
  if(project.kind==="install") return "What planning mistakes can cause installation problems?";
  if(project.kind==="repair") return "Which components can cause this problem?";
  if(project.kind==="jetting") return "What buildup can hydro jetting remove?";
  return "What causes this type of drain blockage?";
}
function comparisonHeading(){
  if(project.kind==="install") return "Which equipment and installation approach fit the property?";
  if(project.kind==="repair") return "When does repair make more sense than replacement?";
  if(project.kind==="jetting") return "When is jetting better than snaking or pipe repair?";
  return "Is cabling, camera inspection, jetting, or pipe repair the right next step?";
}
function serviceDayHeading(s){return project.kind==="install"?"What should a complete installation include?":`What happens during ${s.label.toLowerCase()}?`}
function verificationHeading(s){
  if(/camera|inspection/i.test(s.label)) return "What should the inspection report document?";
  if(project.kind==="install") return "How should the new water heater be commissioned?";
  if(project.kind==="repair") return "How should the repair be tested?";
  if(project.kind==="jetting") return "How do you confirm the pipe is actually clean?";
  return "How do you confirm the drain is fully open?";
}
function serviceCore(s){const r=serviceResearch(s),label=s.label.toLowerCase();return `<div data-unique-copy><section class="section"><div class="shell content-grid"><article class="prose"><p class="eyebrow">Homeowner and property-manager guide</p><h2>When should you invest in ${esc(label)}?</h2><p>${esc(r.signs)}</p><h2>${esc(diagnosisHeading(s))}</h2><p>During a ${esc(label)} evaluation, ${esc(decap(r.diagnosis))}</p><p>For ${esc(label)}, the relevant system includes ${esc(s.system)}. The key scope decision is that ${esc(s.decision)}.</p><h2>${esc(causeHeading(s))}</h2><p>For ${esc(label)}, ${esc(decap(r.causes))}</p><h2>${esc(comparisonHeading())}</h2><p>When comparing options for ${esc(label)}, ${esc(decap(r.comparison))}</p><p>The intended ${esc(label)} outcome is to ${esc(s.outcome)}. If that cannot be achieved safely, the proposal should explain the alternative.</p><h2>What affects the cost of ${esc(label)}?</h2><p>${esc(r.cost)}</p><h2>${esc(serviceDayHeading(s))}</h2><p>On a ${esc(label)} service day, ${esc(decap(r.day))}</p><h2>${esc(verificationHeading(s))}</h2><p>After ${esc(label)}, ${esc(decap(r.verification))}</p></article><aside class="scope-card"><span>Service checklist</span><h2>${esc(s.label)}</h2><dl><dt>System focus</dt><dd>${esc(s.system)}</dd><dt>Target outcome</dt><dd>${esc(s.outcome)}</dd><dt>Decision point</dt><dd>${esc(s.decision)}</dd></dl><a class="button" href="/contact/">Request Service</a></aside></div></section></div>`}
function areaResearch(a){const topic=project.topic.toLowerCase(),byKind={
  drain:{symptoms:`Slow drainage at one fixture usually points toward a local trap or branch. Several affected fixtures, gurgling at the lowest opening, or water returning when another fixture discharges can point toward a shared branch or building sewer. Repeated odor, flies, overflow, or a stoppage that returns after basic clearing deserves a more complete diagnosis.`,choices:`A localized clog may need fixture or branch clearing. Repeated stoppages can justify camera inspection. Wall-adhered grease or scale in suitable pipe may call for jetting, while roots, offsets, bellies, collapses, and deteriorated materials can move the conversation toward repair.`,cost:`Drain-cleaning cost changes with fixture removal, cleanout availability, line length and diameter, blockage material, camera or locating needs, equipment staging, containment, occupancy, and whether the work reveals a repair condition.`},
  repair:{symptoms:`No hot water, slow recovery, unstable temperature, error codes, popping or rumbling, discolored water, ignition trouble, relief-valve discharge, and moisture around the heater point to different failures. The first moisture location and whether the tank itself is leaking are especially important.`,choices:`A component repair may restore a sound unit, but vessel leakage, unavailable parts, repeated faults, unsafe venting, or a repair that is difficult to justify against remaining life can favor replacement. Gas, electric, tankless, heat-pump, recirculated, and commercial systems require different tests.`,cost:`Repair cost depends on equipment type, location, drain-down time, diagnostic access, failed component, parts availability, warranty status, venting or utility corrections, recirculation, required shutdowns, and whether the tank or heat exchanger is still serviceable.`},
  install:{symptoms:`Replacement planning should start before a leaking or unreliable unit creates an urgent decision. Rising hot-water demand, slow recovery, repeated repair, corrosion, unavailable parts, fuel conversion, remodeling, electrification, or a need for more floor space can all justify comparing new systems.`,choices:`Storage gas, storage electric, tankless, heat-pump, recirculated, and commercial systems should be compared using peak demand, recovery, temperature rise, utilities, venting, drainage, space, sound, maintenance, and the building's actual operating pattern.`,cost:`Installation cost changes with capacity, equipment type, removal route, attic or closet access, gas or electrical upgrades, venting, condensate, drain pan and discharge, expansion control, recirculation, permits, inspection, disposal, and finish work by other trades.`},
  jetting:{symptoms:`Recurring grease, sludge, scale, sediment, or light root growth can justify jetting when the host pipe and access are suitable. A collapse, severe offset, belly, missing pipe wall, or inaccessible route is not solved by adding pressure and should be separated from removable buildup.`,choices:`Snaking can open a concentrated blockage; jetting is intended to clean more of the pipe wall. Camera inspection should guide suitability, nozzle and pressure choices, cleaning direction, debris control, and whether the condition should move to repair instead.`,cost:`Jetting cost depends on pipe diameter and length, cleanout access, pre- and post-camera work, deposit type, water source, nozzle and flow requirements, trailer or skid placement, hose routing, containment, debris recovery, shutdown windows, and traffic or tenant protection.`}
}[project.kind];return {topic,...byKind}}
function areaCore(a){const map={
  drain:[`Drain access in ${a.label}`,`${a.propertyMix} That property mix influences whether clearing begins at a fixture, interior cleanout, exterior cleanout, shared stack, or managed service room.`,`${a.plumbingContext} For a drain-specific request, record which openings are affected, where water returns, and whether the symptom changes when other fixtures discharge.`,`${a.access} Cable equipment, cameras, containment, parking, and approval for fixture removal or exterior access should be planned before arrival.`],
  repair:[`Water-heater repair conditions in ${a.label}`,`${a.propertyMix} Heater type, fuel, tank count, recirculation, shared systems, and equipment location can differ substantially among those properties.`,`${a.plumbingContext} For repair triage, add the unit type, approximate capacity, energy source, location, error behavior, leak origin, and whether any hot water remains.`,`${a.access} Attic, closet, garage, roof, mechanical-room, tenant, security, and shutdown access should be confirmed before a repair dispatch.`],
  install:[`Water-heater installation planning in ${a.label}`,`${a.propertyMix} Replacement access, demand, fuel infrastructure, venting, drainage, and inspection coordination therefore vary by building type.`,`${a.plumbingContext} Installation planning should verify capacity, simultaneous demand, current utilities, removal route, pan and drain conditions, service clearances, and upgrade goals.`,`${a.access} Jurisdiction, parking, lifting, stairs, attic openings, management approvals, and approved work windows can change labor and equipment selection.`],
  jetting:[`Hydro jetting suitability in ${a.label}`,`${a.propertyMix} Those buildings can present small branches, large commercial mains, shared stacks, older buried sewers, and very different cleanout configurations.`,`${a.plumbingContext} Jetting suitability depends on host-pipe condition, diameter, camera evidence, deposit type, downstream route, water supply, and a controlled debris plan.`,`${a.access} Trailer or skid placement, hose routing, traffic, gates, loading areas, tenant protection, and wash-water containment should be discussed before mobilization.`]
  }[project.kind],r=areaResearch(a);return `<div data-unique-copy><section class="section"><div class="shell content-grid"><article class="prose"><p class="eyebrow">Local service guide</p><h2>What should ${esc(a.label)} property owners know about ${esc(r.topic)}?</h2><p>${esc(map[1])}</p><h2>Which warning signs should you take seriously?</h2><p>For ${esc(r.topic)} in ${esc(a.label)}, ${esc(r.symptoms)}</p><h2>How is the problem diagnosed before work begins?</h2><p>${esc(map[2])}</p><p>For a ${esc(a.label)} property, a useful ${esc(r.topic)} diagnosis connects the symptom to the affected system, shows what was tested, explains what remains uncertain, and separates a serviceable condition from damage that needs a different scope.</p><h2>Which ${esc(r.topic)} option fits the property?</h2><p>For ${esc(a.label)} properties, ${esc(r.choices)}</p><h2>How do local access and scheduling affect the work?</h2><p>${esc(map[3])}</p><h2>What affects ${esc(r.topic)} cost in ${esc(a.label)}?</h2><p>For work in ${esc(a.label)}, ${esc(r.cost)}</p><p>A ${esc(a.label)} estimate should identify ${esc(r.topic)} diagnostic work, access, protection, equipment or parts, permits, cleanup, testing, and exclusions so competing scopes can be compared on the same basis.</p><h2>Who confirms permits, utilities, and jurisdiction?</h2><p>Before ${esc(r.topic)} work in ${esc(a.label)}, confirm the permit authority, utility provider, municipal limits, MUD, private-system boundary, and restoration rules for the exact property. A mailing name alone cannot establish those requirements for this service scope.</p></article><aside class="scope-card"><span>${esc(a.label)} planning checklist</span><h2>${esc(project.topic)}</h2><dl><dt>Property context</dt><dd>${esc(a.propertyMix)}</dd><dt>Access question</dt><dd>${esc(a.access)}</dd><dt>Jurisdiction check</dt><dd>Exact address, utility, permit authority, and service boundary</dd></dl><a class="button" href="/contact/">Request Service</a></aside></div></section></div>`}

function home(){const priorities=project.services.slice(0,8);const body=`<main id="main-content"><section class="home-hero"><div class="shell home-grid"><div class="home-copy"><p class="eyebrow">Greater Houston ${esc(project.topic.toLowerCase())}</p><h1>${esc(project.homepageH1)}</h1><p class="lede">${esc(project.lede)}</p><div class="actions"><a class="button" href="/contact/">Request Service</a><a href="/services/">Explore all ${project.services.length} services</a></div><ul><li>Residential service guidance</li><li>${areas.length} local service-area guides</li><li>Commercial property information</li></ul></div><div class="hero-art" aria-label="Abstract ${esc(project.topic.toLowerCase())} system illustration"><i></i><i></i><i></i><span>${esc(project.shortName)}</span><b>${esc(project.topic)}</b></div></div></section><section class="section intro"><div class="shell split"><div><p class="eyebrow">Start with the system</p><h2>Match the observed condition to the right service.</h2></div><div class="prose"><p>${esc(kindCopy[project.kind].system)}</p><p>${esc(kindCopy[project.kind].scope)}</p></div></div></section><section class="section"><div class="shell section-head"><div><p class="eyebrow">Featured services</p><h2>Find the service that fits the problem.</h2></div><a href="/services/">Complete service directory</a></div><div class="shell card-grid">${cards(priorities)}</div></section><section class="section dark"><div class="shell split"><div><p class="eyebrow">Greater Houston service areas</p><h2>${areas.length} local guides organized by regional conditions.</h2></div><div class="prose"><p>Property type, access, jurisdiction, utilities, equipment location, and system history can vary widely across the region. Local guides explain the details that matter before service begins.</p><a class="button" href="/service-areas/">Browse service areas</a></div></div><div class="shell region-grid">${areaGroups.map(g=>`<article><span>${String(g.areas.length).padStart(2,"0")}</span><h3>${esc(g.label)}</h3><p>${g.areas.slice(0,5).map(a=>esc(a.label)).join(" · ")}</p></article>`).join("")}</div></section>${faq(`${project.topic} questions for Greater Houston`,`Answers to common service, scope, and property questions.`,[[`How do I choose the right ${project.topic.toLowerCase()} service?`,`Start with the observable symptom, equipment or pipe involved, property type, and desired outcome. Each service guide explains where that option fits and what should be documented.`],[`What information should I gather before requesting service?`,`Record when the issue began, which systems are affected, any visible leakage or damage, previous work, equipment labels, access limitations, and the property ZIP code.`],[`Which Greater Houston communities are included?`,`The service-area directory covers ${areas.length} Houston districts, incorporated cities, suburbs, and nearby communities, each with distinct property and access context.`],[`What should a written service scope include?`,`Look for clear testing, access, materials, permit responsibilities, shutdowns, cleanup, completion evidence, and a process for concealed conditions.`]])}${finalCta(`Get help with ${project.topic.toLowerCase()}.`,`Share the property type, location, affected system, timing, access, and observable condition so the request can be evaluated accurately.`)}</main>`;return page({title:project.homepageH1,description:`Explore ${project.topic.toLowerCase()} services and ${areas.length} detailed service-area guides for homes and commercial properties across Greater Houston.`,route:"/",body})}
function servicesPage(){const h1=`${project.topic} Services`;const body=`<main id="main-content">${hero({eyebrow:`${project.services.length} specialized services`,h1,intro:`Browse ${project.topic.toLowerCase()} services by system, symptom, property type, and desired outcome. Each guide explains when the service fits and what a complete scope should address.`,items:[{label:"Home",route:"/"},{label:"Services"}]})}<section class="section"><div class="shell"><div class="notice"><b>Choose by condition and outcome</b><p>Start with what is happening, the equipment or piping involved, and the result the property needs. Inspection may change the final method or reveal a related repair.</p></div>${groups.map(g=>`<section class="directory-group"><div><p class="eyebrow">Service category</p><h2>${esc(g)}</h2></div><div class="directory-list">${project.services.filter(s=>s.group===g).map(s=>`<a href="${sRoute(s)}"><span>${esc(s.label)}</span><small>${esc(s.situation)}</small><b>→</b></a>`).join("")}</div></section>`).join("")}</div></section>${faq(`${project.topic} service questions`,`How to use the service directory and prepare for the next step.`,[["Can one property need several services?","Yes. Diagnosis, cleaning or repair, inspection, safety work, and maintenance may be separate stages even when they begin with one symptom."],["What details help identify the right service?","Note the affected system, when the condition began, how often it occurs, previous work, visible damage, equipment information, and access limitations."],["Why can the recommended method change?","Field testing may reveal different materials, concealed damage, access constraints, code requirements, or a problem outside the original service scope."],["Where can I find local service information?","Every service guide links to the complete service-area directory, with local property, access, utility, and jurisdiction details."]])}${finalCta("Find the right service for the condition.","Share the affected system, symptoms, timing, property type, previous work, and access details so the scope starts with useful information.")}</main>`;return page({title:h1,description:`Browse ${project.services.length} specialized ${project.topic.toLowerCase()} services with clear guidance on conditions, scope, access, and completion testing.`,route:"/services/",body,active:"services",schema:[breadcrumb([{name:"Home",route:"/"},{name:"Services",route:"/services/"}])]})}
function serviceFaqs(s){const label=s.label.toLowerCase();return [[`Can ${label} correct the condition described on this page?`,`${s.label} may fit when ${s.situation} Inspection still needs to confirm that the requested scope matches the actual cause.`],[`What belongs in a ${label} estimate?`,`The estimate should identify access, method, included materials or equipment, testing, cleanup, exclusions, and the decision point: ${s.decision}.`],[`Which facts can change a ${label} recommendation?`,`Material condition, concealed damage, utilities, safe access, and field test results can change the plan for ${label}.`],[`How should ${label} be verified?`,`Completion testing should show whether the work achieved its stated goal: ${s.outcome}.`]]}
function servicePage(s){const related=s.related.map(x=>serviceBySlug[x]).filter(Boolean);const description=`Learn the warning signs, diagnostic steps, service options, cost factors, scope details, and completion checks for ${s.label.toLowerCase()}.`;const body=`<main id="main-content">${hero({eyebrow:s.group,h1:s.h1,items:[{label:"Home",route:"/"},{label:"Services",route:"/services/"},{label:s.label}]})}${serviceCore(s)}<section class="section related" aria-labelledby="related-title"><div class="shell section-head"><div><p class="eyebrow">Problems that may share the same system</p><h2 id="related-title">Related Services</h2></div><a href="/services/">All services</a></div><div class="shell card-grid related-grid">${cards(related)}</div></section><section class="section" aria-labelledby="service-area-title"><div class="shell section-head"><div><p class="eyebrow">Local property and access guidance</p><h2 id="service-area-title">Service Areas</h2><p>Select a community for property, access, utility, and jurisdiction considerations specific to that area.</p></div><a href="/service-areas/">Area directory</a></div><div class="shell link-groups">${areaGroups.map(g=>`<div><strong>${esc(g.label)}</strong>${g.areas.map(a=>`<a href="${aRoute(a)}">${esc(a.label)}</a>`).join("")}</div>`).join("")}</div></section>${faq(`${s.label} questions`,`Answers specific to the diagnosis, scope, and completion of ${s.label.toLowerCase()}.`,serviceFaqs(s))}${finalCta(`Request ${s.label.toLowerCase()}.`,`Share the symptoms, affected system, property type, timing, previous work, active damage, and access details so the request starts with useful evidence.`)}</main>`;return page({title:s.h1,description,route:sRoute(s),body,active:"services",schema:[breadcrumb([{name:"Home",route:"/"},{name:"Services",route:"/services/"},{name:s.label,route:sRoute(s)}])]})}
function areasPage(){const h1=`${project.topic} Service Areas in Greater Houston`;const body=`<main id="main-content">${hero({eyebrow:`${areas.length} detailed local guides`,h1,intro:`Explore Houston districts, incorporated cities, suburbs, and nearby communities with ${project.topic.toLowerCase()} information shaped by local property, access, utility, and jurisdiction conditions.`,items:[{label:"Home",route:"/"},{label:"Service Areas"}]})}<section class="section"><div class="shell"><div class="notice"><b>Local conditions matter</b><p>Building type, equipment location, foundation, utilities, management access, parking, permits, and approved work windows can change how service is planned.</p></div>${areaGroups.map(g=>`<section class="area-region"><div class="section-head"><div><p class="eyebrow">Regional group</p><h2>${esc(g.label)}</h2></div><span>${g.areas.length} guides</span></div><div class="location-grid">${g.areas.map(a=>`<a href="${aRoute(a)}"><span>${esc(a.region)}</span><h3>${esc(a.label)}</h3><p>${esc(a.context)}</p><b>Open local guide →</b></a>`).join("")}</div></section>`).join("")}</div></section>${faq(`${project.topic} service-area questions`,`What to consider when requesting service for a specific property.`,[["Why do local property conditions matter?","Access, building type, equipment location, utilities, foundation, management rules, and work-hour limits can change labor, equipment, and sequencing."],["Why include both cities and Houston districts?","They represent different property mixes, access conditions, jurisdiction questions, and travel patterns within the wider service region."],["Why is the property ZIP code useful?","A mailing name may cross municipal, county, utility-district, or provider boundaries. The ZIP code helps narrow the exact address and jurisdiction."],["Should permits be confirmed before work begins?","Yes. Permit, inspection, utility, and credential requirements depend on the exact property, system, and scope of work."]])}${finalCta("Request service for your property.","Include the ZIP code, municipality or district, property type, access constraints, affected system, and observed condition.")}</main>`;return page({title:h1,description:`Browse ${areas.length} detailed Greater Houston ${project.topic.toLowerCase()} guides covering local property, access, utility, and jurisdiction considerations.`,route:"/service-areas/",body,active:"areas",schema:[breadcrumb([{name:"Home",route:"/"},{name:"Service Areas",route:"/service-areas/"}])]})}
function areaFaqs(a){const topic=project.topic.toLowerCase();return [[`What information helps plan ${topic} in ${a.label}?`,`For ${topic} at a ${a.label} property, provide the ZIP code, building type, affected system, timing, and access instructions. ${a.access}`],[`How can ${a.label}'s property mix affect ${topic}?`,`${a.propertyMix} For ${topic}, the actual materials, equipment age, utilities, and renovation history still require property-level verification.`],[`Which local access issues can affect a ${topic} appointment in ${a.label}?`,`${a.access} A ${topic} request should also note parking, gates, management approval, work-hour limits, and equipment staging when they apply.`],[`Who confirms ${a.label} permit and utility requirements for ${topic}?`,`Before ${topic}, use the exact ${a.label} property address to confirm its jurisdiction, utility boundary, credential requirements, and regulated scope.`]]}
function areaPage(a){const h1=`${project.topic} in ${a.label}, TX`;const description=`${h1} information covering local property types, system conditions, access, utilities, jurisdiction, and available service options.`;const body=`<main id="main-content">${hero({eyebrow:a.region,h1,intro:`${a.context} This local guide explains the property, access, utility, and planning details that can influence ${project.topic.toLowerCase()} work.`,items:[{label:"Home",route:"/"},{label:"Service Areas",route:"/service-areas/"},{label:a.label}]})}${areaCore(a)}<section class="section related" aria-labelledby="area-service-title"><div class="shell section-head"><div><p class="eyebrow">Available service information</p><h2 id="area-service-title">${esc(project.topic)} Services for ${esc(a.label)}</h2><p>Explore individual guides for symptoms, systems, scope decisions, inspection needs, and completion testing.</p></div><a href="/services/">Service directory</a></div><div class="shell link-groups service-links">${groups.map(g=>`<div><strong>${esc(g)}</strong>${project.services.filter(s=>s.group===g).map(s=>`<a href="${sRoute(s)}">${esc(s.label)}</a>`).join("")}</div>`).join("")}</div></section><section class="section nearby"><div class="shell section-head"><div><p class="eyebrow">Nearby service areas</p><h2>Other ${esc(a.region)} guides</h2></div><a href="/service-areas/">All markets</a></div><div class="shell nearby-links">${areas.filter(x=>x.region===a.region&&x.slug!==a.slug).map(x=>`<a href="${aRoute(x)}">${esc(x.label)}</a>`).join("")}</div></section>${faq(`${project.topic} questions for ${a.label}`,`${project.topic} questions tied to ${a.label} properties, access, utilities, and jurisdiction.`,areaFaqs(a))}${finalCta(`Request service in ${a.label}.`,`Share the affected system, property type, ZIP code, timing, access conditions, previous work, and the result you need.`)}</main>`;return page({title:h1,description,route:aRoute(a),body,active:"areas",schema:[breadcrumb([{name:"Home",route:"/"},{name:"Service Areas",route:"/service-areas/"},{name:a.label,route:aRoute(a)}])]})}
function processPage(){const h1=`How ${project.topic} Service Works`;const steps=[["Describe the condition","Record the property type, affected system, timing, current function, active damage, known equipment or pipe details, previous work, and access."],["Choose the closest service","Use the service catalog to separate diagnosis, cleaning, repair, installation, inspection, safety work, and maintenance."],["Inspect and test the system","Confirm materials, equipment, access, utilities, safety conditions, and the actual cause before committing to a method."],["Review the written scope","Define testing, access, materials, permits, shutdowns, cleanup, completion evidence, exclusions, and work by other trades."],["Verify the finished work","Check operation, flow, temperature, drainage, controls, leak points, cleanup, and any inspection or follow-up documentation appropriate to the service."]];const body=`<main id="main-content">${hero({eyebrow:"From symptom to completed scope",h1,intro:"A clear service process connects the observable condition to field testing, an agreed scope, protected work areas, and documented completion.",items:[{label:"Home",route:"/"},{label:"Process"}]})}<section class="section"><div class="shell timeline">${steps.map(([h,p],i)=>`<article><span>${String(i+1).padStart(2,"0")}</span><div><h2>${esc(h)}</h2><p>${esc(p)}</p></div></article>`).join("")}</div></section>${faq(`${project.topic} process questions`,`What to expect when the condition, scope, and completion criteria are clearly documented.`,[["Why does service begin with symptoms instead of a requested method?","The same symptom can have several causes. Inspection and testing help avoid work that treats the wrong system or misses a related defect."],["What belongs in the written scope?","The scope should state testing, access, materials, permits, shutdowns, protection, cleanup, completion evidence, exclusions, and how concealed conditions are handled."],["When might another trade be required?","Electrical, gas, structural, roofing, environmental, utility, restoration, or excavation work may require separate coordination depending on the system and findings."],["How should completion be verified?","Verification should match the service: flow testing, temperature and control checks, leak inspection, camera evidence, pressure checks, startup documentation, or required inspection approval."]])}${finalCta("Start with the condition you can observe.","Include the affected system, property type, timing, previous work, current damage, access, and the outcome you need.")}</main>`;return page({title:h1,description:`Learn the five-step ${project.topic.toLowerCase()} service process from condition review and testing through scope approval and completion verification.`,route:"/process/",body,active:"process",schema:[breadcrumb([{name:"Home",route:"/"},{name:"Process",route:"/process/"}])]})}
function contactPage(){const h1=`Request ${project.topic} Service`;const body=`<main id="main-content">${hero({eyebrow:"Service request information",h1,intro:"Gather the property, affected system, timing, observable condition, and access details needed to identify the right service and scope.",items:[{label:"Home",route:"/"},{label:"Contact"}]})}<section class="section"><div class="shell contact-grid"><div class="prose"><p class="eyebrow">Helpful request details</p><h2>Describe what is happening before choosing a method.</h2><p>${esc(kindCopy[project.kind].local)}</p><ul class="check-list"><li>affected fixture, line, or equipment</li><li>when the condition began</li><li>visible leakage or active damage</li><li>previous service or repair history</li><li>property and equipment access</li><li>preferred contact method</li></ul></div><form class="lead-form" data-lead-form novalidate><div class="honeypot" aria-hidden="true"><label for="website">Website</label><input id="website" name="website" tabindex="-1"></div><div class="form-grid"><div class="field"><label for="name">Name</label><input id="name" name="name" autocomplete="name" data-required><span data-error-for="name"></span></div><div class="field"><label for="contact">Email or phone</label><input id="contact" name="contact" autocomplete="email" data-required><span data-error-for="contact"></span></div><div class="field"><label for="zip">Property ZIP code</label><input id="zip" name="zip" inputmode="numeric" maxlength="5" data-required><span data-error-for="zip"></span></div><div class="field"><label for="property">Property type</label><select id="property" name="property" data-required><option value="">Select one</option><option>House</option><option>Apartment or multifamily</option><option>Commercial property</option><option>Institutional or industrial property</option><option>Other</option></select><span data-error-for="property"></span></div><div class="field full"><label for="service">Service needed</label><select id="service" name="service" data-required><option value="">Select one</option>${project.services.map(s=>`<option value="${s.slug}">${esc(s.label)}</option>`).join("")}</select><span data-error-for="service"></span></div><div class="field full"><label for="concern">Describe the condition</label><textarea id="concern" name="concern" data-required></textarea><span data-error-for="concern"></span></div></div><p class="form-note">Online request delivery is temporarily unavailable. Use these fields to organize the service details, and do not include payment information, access codes, medical details, or other sensitive data.</p><button class="button" type="submit">Check Request Details</button><div class="form-status" role="status" aria-live="polite" data-form-status></div></form></div></section>${faq(`${project.topic} service-request questions`,`Details that help classify the condition and prepare an accurate scope.`,[["Why is the property ZIP code requested?","The ZIP code helps identify the correct service area, jurisdiction, utility boundary, travel considerations, and local property context."],["What should I include in the condition description?","Explain what you see, hear, smell, or feel; which fixtures or equipment are affected; when it began; whether it is changing; and any previous work."],["Should urgent hazards be submitted online?","No. For fire, gas odor, electrical danger, flooding near energized equipment, or another immediate hazard, use the appropriate emergency or utility contact."],["What information should never be included?","Do not provide payment card numbers, door or gate codes, government identifiers, medical information, insurance credentials, or unrelated private details."]])}</main>`;return page({title:h1,description:`Prepare a ${project.topic.toLowerCase()} service request with property, system, timing, access, and condition details for accurate scope planning.`,route:"/contact/",body,active:"contact",schema:[breadcrumb([{name:"Home",route:"/"},{name:"Contact",route:"/contact/"}])]})}
function privacyPage(){const h1=`Privacy Information for ${project.name}`;const body=`<main id="main-content">${hero({eyebrow:"Privacy and data handling",h1,intro:"This page explains what information a service request may contain, what should be excluded, and how online request delivery is currently handled.",items:[{label:"Home",route:"/"},{label:"Privacy"}]})}<section class="section"><div class="shell legal"><h2>Information you may provide</h2><p>A service request may include a name, contact method, property ZIP code, property type, service selection, and a short condition description. Do not include payment details, access codes, government identifiers, medical information, insurance credentials, or unrelated private information.</p><h2>Online request availability</h2><p>Online request delivery is temporarily unavailable. The form can help organize the required details, but entries are not sent to an email address, CRM, service provider, or other recipient.</p><h2>Cookies, analytics, and advertising</h2><p>This website does not currently use analytics, advertising pixels, call tracking, or session recording. This privacy information will be updated if measurement or advertising tools are added.</p><h2>Security and retention</h2><p>When online request delivery becomes available, this page will identify the recipient, purpose, retention period, deletion procedure, privacy contact, and safeguards used to protect submitted information.</p></div></section>${faq(`Privacy questions for ${project.name}`,"Answers about request information and website tracking.",[["Are form entries stored?","No. Online request delivery is temporarily unavailable, and the form does not intentionally store entries in cookies or browser storage."],["Are request details shared with a service provider?","No. Entries are not currently sent to a service provider or another recipient."],["Are tracking cookies installed?","No analytics, advertising, call-tracking, or recording tools are configured."],["What information should be excluded from a request?","Do not include payment card numbers, access codes, government identifiers, medical information, insurance credentials, or unrelated sensitive details."]])}</main>`;return page({title:h1,description:`Read the request-information, online-delivery, cookie, tracking, security, and retention details for ${project.name}.`,route:"/privacy/",body,schema:[breadcrumb([{name:"Home",route:"/"},{name:"Privacy",route:"/privacy/"}])]})}
function notFound(){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page Not Found</title><meta name="description" content="The requested page could not be found."><meta name="robots" content="noindex, nofollow"><link rel="canonical" href="${abs("/404.html")}"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/styles.css"></head><body class="design-${project.design}"><main class="not-found"><div><span>404</span><h1>Page Not Found</h1><p>The route is not part of this ${esc(project.topic.toLowerCase())} service map.</p><a class="button" href="/services/">Browse services</a><a href="/service-areas/">Browse service areas</a></div></main></body></html>`}

function js(){return `const menuToggle=document.querySelector('[data-menu-toggle]'),nav=document.querySelector('[data-nav]'),dropdowns=[...document.querySelectorAll('[data-dropdown]')];const close=(except=null)=>dropdowns.forEach(d=>{if(d===except)return;d.classList.remove('is-open');d.querySelector('[data-dropdown-toggle]')?.setAttribute('aria-expanded','false')});dropdowns.forEach(d=>{const t=d.querySelector('[data-dropdown-toggle]');t?.addEventListener('click',()=>{const open=!d.classList.contains('is-open');close(open?d:null);d.classList.toggle('is-open',open);t.setAttribute('aria-expanded',String(open))});d.addEventListener('keydown',e=>{if(e.key==='Escape'){d.classList.remove('is-open');t?.setAttribute('aria-expanded','false');t?.focus()}})});menuToggle?.addEventListener('click',()=>{const open=menuToggle.getAttribute('aria-expanded')!=='true';menuToggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open);if(!open)close()});nav?.addEventListener('click',e=>{if(e.target.closest('a')){menuToggle?.setAttribute('aria-expanded','false');nav.classList.remove('is-open');close()}});document.addEventListener('click',e=>{if(!e.target.closest('[data-dropdown]'))close()});document.querySelectorAll('[data-year]').forEach(x=>x.textContent=new Date().getFullYear());const form=document.querySelector('[data-lead-form]');if(form){const status=form.querySelector('[data-form-status]'),required=[...form.querySelectorAll('[data-required]')],error=(f,m='')=>{f.setAttribute('aria-invalid',m?'true':'false');form.querySelector('[data-error-for="'+f.id+'"]')?.replaceChildren(m)};required.forEach(f=>{f.addEventListener('input',()=>error(f));f.addEventListener('change',()=>error(f))});form.addEventListener('submit',e=>{e.preventDefault();status.className='form-status';status.textContent='';if(form.elements.website?.value)return;let valid=true;required.forEach(f=>{if(!f.value.trim()){error(f,'Please complete this field.');valid=false}else error(f)});const c=form.querySelector('#contact'),z=form.querySelector('#zip');if(c?.value&&!c.value.includes('@')&&c.value.replace(/\\D/g,'').length<10){error(c,'Enter a valid email or 10-digit phone number.');valid=false}if(z?.value&&!/^\\d{5}$/.test(z.value)){error(z,'Enter a 5-digit ZIP code.');valid=false}if(!valid){status.textContent='Please review the highlighted fields.';status.classList.add('form-status--error','is-visible');required.find(f=>f.getAttribute('aria-invalid')==='true')?.focus();return}status.textContent='Test mode: the request was validated in this browser but was not transmitted or stored.';status.classList.add('form-status--success','is-visible')})}`}
