function favicon(){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="10" fill="${project.palette.ink}"/><circle cx="32" cy="32" r="19" fill="none" stroke="${project.palette.accent2}" stroke-width="7"/><path d="M12 32h40M32 12v40" stroke="${project.palette.accent}" stroke-width="7"/></svg>`}
function write(route,html){const file=route==="/"?path.join(out,"index.html"):route==="/404.html"?path.join(out,"404.html"):path.join(out,route.slice(1),"index.html");fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,html,"utf8")}
fs.mkdirSync(path.join(out,"assets"),{recursive:true});for(const entry of fs.readdirSync(out,{withFileTypes:true})){if(entry.isDirectory()&&entry.name!=="assets")fs.rmSync(path.join(out,entry.name),{recursive:true,force:true});else if(entry.isFile()&&entry.name.endsWith(".html"))fs.rmSync(path.join(out,entry.name))}
const styleText=css().replace(/(border-radius:[^;{}]+)(\.mark i\{)/,"$1}$2");
const scriptText=js().replace("Test mode: the request was validated in this browser but was not transmitted or stored.","Your request details are complete. Online request delivery is temporarily unavailable.");
fs.writeFileSync(path.join(out,"assets","styles.css"),styleText,"utf8");fs.writeFileSync(path.join(out,"assets","main.js"),scriptText,"utf8");fs.writeFileSync(path.join(out,"assets","favicon.svg"),favicon(),"utf8");
write("/",home());write("/services/",servicesPage());project.services.forEach(s=>write(sRoute(s),servicePage(s)));write("/service-areas/",areasPage());areas.forEach(a=>write(aRoute(a),areaPage(a)));write("/process/",processPage());write("/contact/",contactPage());write("/privacy/",privacyPage());write("/404.html",notFound());
console.log(`Generated ${project.services.length+areas.length+7} pages for ${project.name}.`);
